import time
from collections import OrderedDict


class TTLCache:
    """A thread-unsafe LRU cache with per-entry time-to-live."""

    def __init__(self, capacity: int, ttl: float, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        if ttl <= 0:
            raise ValueError("ttl must be > 0")
        self._capacity = capacity
        self._ttl = ttl
        self._clock = clock
        # OrderedDict maintains LRU order: first item = LRU, last item = MRU
        # Each value is (value, set_time)
        self._store: OrderedDict = OrderedDict()

    def _is_expired(self, set_time: float) -> bool:
        return self._clock() - set_time >= self._ttl

    def get(self, key, default=None):
        if key not in self._store:
            return default
        value, set_time = self._store[key]
        if self._is_expired(set_time):
            return default
        # Mark as most-recently-used
        self._store.move_to_end(key)
        return value

    def set(self, key, value):
        now = self._clock()
        if key in self._store:
            # Remove existing entry so re-insertion places it at the end (MRU)
            del self._store[key]
        self._store[key] = (value, now)
        # Enforce capacity
        if len(self._store) > self._capacity:
            # First pass: drop all expired entries
            expired_keys = [
                k for k, (_, st) in self._store.items() if self._is_expired(st)
            ]
            for k in expired_keys:
                del self._store[k]
            # Second pass: evict LRU entries if still over capacity
            while len(self._store) > self._capacity:
                self._store.popitem(last=False)

    def __len__(self):
        now = self._clock()
        return sum(
            1 for (_, st) in self._store.values() if now - st < self._ttl
        )

    def delete(self, key) -> bool:
        if key not in self._store:
            return False
        _, set_time = self._store[key]
        if self._is_expired(set_time):
            # Entry is dead; remove it but report no live entry was removed
            del self._store[key]
            return False
        del self._store[key]
        return True

    def __contains__(self, key):
        if key not in self._store:
            return False
        _, set_time = self._store[key]
        return not self._is_expired(set_time)

    def __repr__(self):
        return (
            f"TTLCache(capacity={self._capacity}, ttl={self._ttl}, "
            f"size={len(self)})"
        )
